import{_ as t,o as e,c as r,a5 as n}from"./chunks/framework.BYXPg_yw.js";const d="/RBQ/nightly/images/app/dashboard-detail.pc.ko.png",m=JSON.parse('{"title":"개발자 모드","description":"","frontmatter":{"layout":"doc","outline":"deep","title":"개발자 모드"},"headers":[],"relativePath":"ko/manual/gui/developer-mode.md","filePath":"ko/manual/gui/developer-mode.md","lastUpdated":1792759058000}'),s={name:"ko/manual/gui/developer-mode.md"};function c(a,o,g,i,l,h){return e(),r("div",null,[...o[0]||(o[0]=[n('<h1 id="개발자-모드" tabindex="-1">개발자 모드 <a class="header-anchor" href="#개발자-모드" aria-label="Permalink to &quot;개발자 모드&quot;">​</a></h1><p>앱은 기본적으로 <strong>운용자 등급</strong>으로 동작합니다. 개발자 모드를 켜면 진단·설정·정비 기능이 화면에 추가로 나타납니다. 이 페이지에 <strong>개발자 모드로만 열리는 것을 전부 모아 두었습니다</strong> — 다른 페이지들은 일반 운용에 필요한 것만 다룹니다.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>개발자 모드에서는 <strong>평소의 안전장치를 거치지 않고 로봇을 움직이는 명령</strong>(관절 잠금, 강제 자세)이 열립니다. 필요할 때만 켜고, 조작 전에 각 항목의 경고를 읽으세요.</p></div></div><h2 id="turn-on" tabindex="-1">켜고 끄기 <a class="header-anchor" href="#turn-on" aria-label="Permalink to &quot;켜고 끄기 {#turn-on}&quot;">​</a></h2><ol><li>허브 오른쪽 위의 프로필 버튼을 누릅니다.</li><li><strong>개발자 모드</strong> 토글을 켭니다. 부제에 <em>켤 때 암호 필요</em> 라고 적혀 있습니다.</li><li><strong>개발자 모드 암호</strong> 창에 암호를 입력하고 <strong>확인</strong>을 누릅니다. 틀리면 <em>암호가 올바르지 않습니다</em> 가 표시되고 입력칸이 비워집니다.</li></ol><p>토글을 끄면 즉시 운용자 등급으로 돌아갑니다.</p><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">경고</p><p>암호는 <strong>Rainbow Robotics 에서 개별로 발급</strong>합니다. 이 매뉴얼에는 적지 않으며, 받은 암호를 외부에 알리지 마세요. 필요하시면 <a href="/RBQ/nightly/ko/manual/support/">기술지원 요청</a>으로 문의하세요.</p></div></div><h3 id="by-account" tabindex="-1">계정으로 켜지는 경우 <a class="header-anchor" href="#by-account" aria-label="Permalink to &quot;계정으로 켜지는 경우 {#by-account}&quot;">​</a></h3><p>프로필 메뉴의 <code>접근 코드로 로그인</code>으로 로그인하면 등급은 <strong>계정을 따릅니다.</strong> 로그인 중에는 프로필 메뉴에 개발자 모드 토글 대신 계정과 레벨이 표시됩니다. 일반 등급으로 돌아가려면 같은 메뉴의 <code>로그아웃</code>을 누르세요.</p><p>앱을 켜거나 다시 화면에 띄울 때마다 서버에서 계정을 다시 확인합니다. 계정이 비활성·삭제됐거나 코드가 바뀌었으면 로그아웃됩니다. 인터넷이 없으면 서버에 닿을 때까지 그대로 둡니다.</p><h2 id="what-changes" tabindex="-1">화면별로 무엇이 늘어나나 <a class="header-anchor" href="#what-changes" aria-label="Permalink to &quot;화면별로 무엇이 늘어나나 {#what-changes}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>화면</th><th>개발자 모드에서 추가되는 것</th></tr></thead><tbody><tr><td><a href="#control-home">제어 홈</a></td><td><code>조종</code> 팝오버의 외부 조종 토글 · <code>장애물회피</code> 도구 버튼</td></tr><tr><td><a href="#motion">모션 명령</a></td><td><strong>포지션 제어</strong> 그룹 (강제 자세)</td></tr><tr><td><a href="#gamepad">게임패드</a></td><td>감도·데드존, 버튼 매핑, 외부 조종, 개발자 옵션, 진단·마법사</td></tr><tr><td><a href="#dashboard">대시보드</a></td><td><strong>로봇</strong> · <strong>비전</strong> · <strong>R-PC</strong> 탭, 요약의 전원 추가</td></tr><tr><td><a href="#connection">연결</a></td><td>안드로이드·iOS 의 <code>주소로 연결</code> 카드 · <code>Vision PC IP (선택)</code> 칸</td></tr><tr><td><a href="#emergency">비상 정지</a></td><td>포지션 제어를 통한 강제 복구</td></tr><tr><td><a href="#board-firmware">정비 › 펌웨어 업데이트</a></td><td>화면 아래 <strong>보드별 상태</strong> 표 — 보드 하나 · 모터 묶음 업데이트</td></tr><tr><td><a href="#ptz-check">정비 › PTZ 점검</a></td><td><code>기본 검사 시작</code> · <code>에이징 검사 시작</code> — 1~18단계, 전류 영점을 다시 재서 저장</td></tr><tr><td><a href="#maintenance">정비</a></td><td><code>비전</code>, <code>설정 파일</code>, <code>팔</code> 섹션</td></tr><tr><td><a href="/RBQ/nightly/ko/manual/gui/maintenance.html#led-bottom">정비 › 전원 / 시스템</a></td><td>하단 상태 LED 창의 <code>꺼 두기</code>·<code>켜 두기</code>·<code>깜빡이기</code>, R·G·B(0~255), 켜는·끄는 시간(10~2550 ms)과 반복 횟수(<code>0</code>이면 계속) — 일반 사용자는 <code>꺼 두기</code>와 <code>추천 설정</code>만 고릅니다</td></tr><tr><td>로그</td><td><strong>없음</strong> — 이 화면은 등급에 따라 달라지지 않습니다</td></tr></tbody></table><h2 id="control-home" tabindex="-1">제어 홈 <a class="header-anchor" href="#control-home" aria-label="Permalink to &quot;제어 홈 {#control-home}&quot;">​</a></h2><ul><li><p><strong>조종</strong> 팝오버에 <strong>외부 조종 (SLAM·SDK)</strong> 토글이 추가되어 조종권을 외부 프로그램에 넘길 수 있습니다. 켜져 있는 동안 상단바에 <code>SLAM</code> 칩이 표시되며, 그 칩으로 다시 끕니다.</p></li><li><p>도구 버튼에 <strong>조종</strong> 옆으로 <strong>장애물회피</strong>가 추가됩니다. 누르면 <strong>장애물 설정</strong> 패널이 열립니다.</p><ul><li><code>장애물 지도 생성</code> — 메인 스위치입니다. 켜 두면 로봇이 장애물 지도를 만들고, 뷰포트에 <code>화면 표시</code>에서 고른 것이 나옵니다: <code>전방 카메라</code>, <code>후방 카메라</code>, <code>3D</code>, <code>2D</code>. 여러 개를 고르면 뷰포트가 그 수만큼 나뉘며, 최소 하나는 선택된 채로 남습니다. 로봇이 지도를 보내기 전에는 <code>2D</code> 칸에 <code>장애물 지도 수신 대기 중</code>이 표시됩니다.</li><li><code>장애물 회피</code> — 켜 두면 로봇이 진행 방향의 장애물에 대응합니다. <code>장애물 지도 생성</code>이 켜져 있을 때만 켤 수 있으며, 그 전에는 옆에 <code>장애물 지도를 먼저 생성해주세요</code>가 표시됩니다.</li><li><code>회피모드</code> — <code>회피</code>는 장애물을 돌아서 지나가고, <code>정지</code>는 장애물 앞에서 멈춥니다.</li><li><code>장애물 안전거리</code> — 로봇이 장애물과 유지하는 거리로, 0.20 – 0.50 m 입니다.</li><li><code>회피 허용 범위</code> — 장애물을 돌아가려고 옆으로 벗어날 수 있는 폭으로, 0.50 – 1.00 m 입니다. <code>회피</code>에서만 적용됩니다.</li></ul><p><code>장애물 회피</code> 아래 항목은 두 스위치가 모두 켜져야 활성화되며, 그 전에는 흐리게 표시됩니다. 슬라이더에서 손을 떼면 값이 전송됩니다. 시뮬레이터에서는 이 버튼이 나오지 않습니다.</p></li></ul><p>→ <a href="/RBQ/nightly/ko/manual/gui/control-home.html">제어 홈</a></p><h2 id="motion" tabindex="-1">모션 명령 — 포지션 제어 <a class="header-anchor" href="#motion" aria-label="Permalink to &quot;모션 명령 — 포지션 제어 {#motion}&quot;">​</a></h2><p><strong>모션 선택</strong> 그리드에 <strong>포지션 제어</strong> 그룹이 추가됩니다. (<strong>AI 모션</strong> 그룹은 모든 등급에 열려 있습니다 — <a href="/RBQ/nightly/ko/manual/gui/motion-commands.html">모션 명령</a> 참고.)</p><p><strong>포지션 제어</strong> — <code>Lock Joints</code> · <code>Position Sit</code> · <code>Position Stand</code> — 는 일반 전환을 거치지 않고 자세를 강제합니다. 같은 항목이 <code>SIT</code> 길게 누르기 목록에도 있습니다. 휠 로봇에서는 <strong>정밀·보정</strong> 그룹에 <code>HIGH SPEED</code> 도 추가됩니다.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>포지션 제어는 궤적 없이 자세를 바꿉니다. <strong>평지에서 로봇이 바닥에 있을 때만</strong> 쓰세요. 일반 복구가 통하지 않을 때를 위한 수단입니다.</p></div></div><p>→ <a href="/RBQ/nightly/ko/manual/gui/motion-commands.html">모션 명령</a> · <a href="/RBQ/nightly/ko/manual/gui/emergency.html">비상 정지</a></p><h2 id="gamepad" tabindex="-1">게임패드 <a class="header-anchor" href="#gamepad" aria-label="Permalink to &quot;게임패드 {#gamepad}&quot;">​</a></h2><p><strong>설정 › 게임패드</strong>에 아래가 추가됩니다.</p><p><strong>반응</strong></p><ul><li><code>게임패드 감도</code> — 물리 스틱의 입력 응답 곡선(가상 조이스틱 설정과 별개).</li><li><code>데드존</code> — 중심 무시 범위. 기기 자체 데드존에 추가로 적용됩니다.</li></ul><p><strong><code>버튼 매핑</code></strong> — 컨트롤러 그림에서 버튼을 탭해 로봇 모션을 할당합니다. 십자키와 스틱 가운데 버튼도 매핑할 수 있습니다. 매핑된 버튼은 그림 아래에 목록으로 나오고 <code>×</code>로 지웁니다. 매핑하려면 컨트롤러가 연결돼 있어야 하며, 버튼을 누르면 그림에 불이 들어옵니다.</p><p><strong><code>외부 조종 (SLAM·SDK)</code></strong> — 로봇 조종권을 외부에 넘깁니다. 스위치는 로봇의 실제 상태를 반영하므로 다른 클라이언트가 바꿔도 함께 갱신됩니다. 제어 홈의 <code>조종</code> 팝오버에도 같은 스위치가 있습니다.</p><p><strong><code>개발자 옵션</code></strong></p><table tabindex="0"><thead><tr><th>항목</th><th>동작</th></tr></thead><tbody><tr><td><code>전체 버튼 전송</code></td><td>OFF = L1/R1만 로봇에 전송(안전 기본값). ON 이면 모든 버튼을 전달해 <strong>L1+B 같은 조합키</strong>가 동작합니다. 개발자 모드로 올라가면 자동으로 켜지고, 일반 사용자로 돌아가면 다시 꺼집니다</td></tr><tr><td><code>원 스틱 모드</code></td><td>한 손 조작 — 좌우 스틱의 가로축만 서로 바꿉니다(세로축은 각 스틱에 남습니다)</td></tr><tr><td><code>크루즈 컨트롤</code></td><td>R3로 크루즈 시작, 십자키 위/아래로 속도 증감. TROT 계열 보행 중에만 동작합니다</td></tr><tr><td><code>발행 주기 — {hz}Hz</code></td><td>조이스틱 프레임 전송 주기(기본 40 Hz). 낮추면 지연이 늘고 높이면 트래픽이 늡니다</td></tr><tr><td><code>입력 진단</code> › <code>진단 열기</code></td><td><code>게임패드 진단</code> 화면 — <code>연결된 기기</code>(이름·VID:PID·축), <code>축 (원시값)</code> 실시간 막대, <code>버튼 이벤트</code> 키코드 로그. 매핑 전에 낯선 컨트롤러를 확인할 때 씁니다</td></tr><tr><td><code>매핑 마법사</code> › <code>마법사 시작</code></td><td>안내에 따라 조작해 이 기기 전용 프로파일을 만듭니다. 미지의 컨트롤러이거나 스틱 배치가 어긋날 때 사용합니다</td></tr><tr><td><code>마법사 프로파일 삭제</code></td><td>연결된 기기에 마법사 프로파일이 있을 때만 표시됩니다. 지우고 자동 인식으로 되돌립니다</td></tr></tbody></table><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p><code>전체 버튼 전송</code>과 <code>크루즈 컨트롤</code>은 버튼 입력에 대한 로봇의 반응을 바꿉니다. 켠 뒤에는 넓은 공간에서 먼저 시험하고, E-STOP 을 바로 누를 수 있는 위치에 두세요.</p></div></div><p>→ <a href="/RBQ/nightly/ko/manual/gui/gamepad.html">게임패드</a></p><h2 id="dashboard" tabindex="-1">대시보드 <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;대시보드 {#dashboard}&quot;">​</a></h2><p><img src="'+d+'" alt="로봇 상태표"></p><p>제목 아래에 <strong>요약</strong> · <strong>로봇</strong> · <strong>비전</strong> · <strong>R-PC</strong> 네 탭이 나타납니다. 요약에는 <strong>전원 정비 ▸</strong>(시스템 카드)가 추가됩니다.</p><p><strong>로봇</strong> 탭의 표:</p><ul><li><strong>전원 · PDU</strong> — 제목에 PDU 배터리 %. 레일별(<strong>TOTAL</strong>, <strong>BAT L</strong>, <strong>BAT R</strong>, <strong>LEGS</strong>, <strong>ADDON</strong>, <strong>EXTERN</strong>, <strong>CHARGE</strong>) 전압·전류·온도·<strong>상태</strong>(ON / OFF). CHARGE 행 <strong>상태</strong> 칸에는 켜진 것의 이름이 적힙니다: <strong>도킹</strong> / <strong>포트</strong>.</li><li><strong>장치 전원 · 12V/5V</strong> — 장치 레일별 <strong>상태</strong>(ON / OFF).</li><li><strong>IMU</strong> — R(x), P(y), Y(z)의 <strong>ANGLE°</strong>, <strong>GYRO (rad/s)</strong>, <strong>ACC (m/s²)</strong>. 표 아래에 <strong>IMU 캘리브레이션 ▸</strong> 바로가기.</li><li><strong>관절 · JOINT</strong> — 관절마다 <strong>ID</strong>, <strong>STATUS</strong>, <strong>ERR</strong>, <strong>°C B/S</strong>(보드/스테이터 온도), <strong>ANGLE°</strong>, <strong>Nm</strong>(관절 토크), <strong>A</strong>(모터 전류), <strong>KP (Nm/rad)</strong>·<strong>KD (Nm·s/rad)</strong>(물리 단위 관절 게인). STATUS 는 <em>C·H·R</em> — <strong>C</strong> 연결(<strong>N</strong> 미연결), <strong>H</strong> 원점, <strong>R</strong> 구동. 초록 = 구동·원점 모두, 주황 = 구동만, 빨강 = 그 외. 온도는 60 °C 주황, 70 °C 빨강이고 전류는 ±15 A 를 넘으면 빨강입니다. 로봇 소프트웨어가 구버전이면 전류·게인을 보내지 않으므로 그 로봇에서는 이 칸들이 의미가 없습니다 — 로봇을 갱신해야 읽을 수 있습니다.</li><li><strong>팔 · ARM</strong> — 팔이 달렸을 때 나오며 칸 구성은 관절 표와 같습니다. 전류 한계만 ±5 A 입니다.</li></ul><p><strong>비전</strong> 탭 — <strong>비전 정비 ▸</strong> 가 붙은 <strong>비전 프로그램</strong> 목록, <strong>비전 센서</strong> 표(STATUS, RGB / IR / 3D fps, EMIT).</p><p><strong>R-PC</strong> 탭 — 로봇 PC 가 자기에 대해 알려 주는 것 전부, 카드 셋:</p><ul><li><strong>호스트</strong> — <strong>호스트 이름</strong>, <strong>OS</strong>, <strong>커널</strong>, <strong>아키텍처</strong>, <strong>SW 버전</strong>, <strong>패키지 계열</strong>, 이어서 <strong>마지막 부팅</strong>, <strong>가동 시간</strong>, <strong>부팅 기록</strong>, <strong>저장장치</strong> 아래 디스크마다 사용량 막대. 배지는 실시간 커널이면 <strong>PREEMPT_RT</strong>, 아니면 <strong>비 RT 커널</strong>.</li><li><strong>CPU · 메모리</strong> — <strong>모델</strong>, <strong>코어</strong>, <strong>격리 코어</strong>, <strong>클럭</strong>(현재 / 최대 MHz), <strong>부하 (1/5/15분)</strong>, <strong>온도</strong>, <strong>스로틀</strong>, <strong>스로틀 누적</strong>; <strong>RT 코어 사용률</strong> — 실시간 코어마다 코어 번호와 역할(daemon, task, can, comm)을 붙인 막대, 그리고 <strong>IRQ</strong> · <strong>Heightmap</strong> 코어; <strong>MEM</strong> · <strong>SWAP</strong> 막대; <strong>프로세스 (CPU · 메모리)</strong> — RBQ 프로그램별 CPU 점유율과 메모리(많이 쓰는 순).</li><li><strong>네트워크</strong> — 네트워크 포트마다 상태, <strong>IPv4</strong>, <strong>링크 속도</strong>(반이중이면 주황 <strong>반이중</strong>), WiFi 는 <strong>신호</strong>(dBm), <strong>트래픽</strong>(받기 ↓ / 보내기 ↑, 5초 평균). 나머지는 <strong>상세 ▸</strong> 를 눌러 펼칩니다 (숨은 값에 오류가 있으면 접힌 줄이 주황 <strong>상세 — 오류 있음</strong>): <strong>MAC</strong>, 그리고 <code>ifconfig</code> 와 같은 값: <strong>RX</strong> · <strong>TX</strong>(패킷 · 바이트), <strong>RX 오류</strong> · <strong>TX 오류</strong>(errors · dropped · overruns · frame / carrier · collisions — 오류가 있으면 주황), <strong>플래그</strong>, <strong>MTU</strong>, <strong>txqueuelen</strong>, <strong>장치</strong>(드라이버 · 버스 주소), <strong>인터럽트 · 메모리</strong>. CAN 포트는 그 위에 <strong>CAN 상태</strong>(ERROR-ACTIVE 초록, ERROR-WARNING · ERROR-PASSIVE 주황, BUS-OFF 빨강), <strong>비트레이트</strong>(데이터 구간 포함), <strong>에러 카운터</strong>, <strong>버스 이벤트</strong>, <strong>자동 재시작</strong>이 더 붙습니다.</li></ul><p>로봇 소프트웨어가 구버전이면 실시간 값(온도·코어·메모리·프로세스·가동 시간)만 옵니다. 카드에 그 안내가 뜨고 나머지 칸은 <code>—</code> 입니다. 로봇을 갱신해야 볼 수 있습니다.</p><p>→ <a href="/RBQ/nightly/ko/manual/gui/dashboard.html">대시보드</a></p><h2 id="connection" tabindex="-1">연결 <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;연결 {#connection}&quot;">​</a></h2><p>안드로이드·iOS 의 <strong>로봇 추가</strong>에 <code>주소로 연결</code> 카드가 나타납니다(웹 빌드·데스크탑 앱·Steam Deck 은 항상 보입니다). 그 아래 접힌 <code>Vision PC IP (선택)</code> 이 있습니다. 비전 PC 가 별도 주소를 쓰는 로봇을 위한 것이며, 비워 두면 로봇 IP 를 그대로 씁니다. 연결하면 로봇 IP 와 함께 그 로봇에 저장됩니다.</p><p><strong>시스템 종합 상태</strong>의 문제 목록이 부위별로 묶이지 않고 항목마다 부품·값·기준과 함께 나옵니다. 예를 들어 <code>HRK2 모터 연결 끊김</code>, <code>HLK5 모터 온도 84°C (기준 80°C)</code>입니다. 빨간 <code>확인 필요:</code> 배너도 첫 번째 고장과 나머지 개수(<code>외 2건</code>)를 보여 줍니다. 카메라 항목은 <strong>정비 › 비전</strong>을 엽니다.</p><p>→ <a href="/RBQ/nightly/ko/manual/gui/connection.html">연결</a></p><h2 id="emergency" tabindex="-1">비상 정지 — 강제 복구 <a class="header-anchor" href="#emergency" aria-label="Permalink to &quot;비상 정지 — 강제 복구 {#emergency}&quot;">​</a></h2><p>점선 <code>모션</code> 버튼으로 여는 <code>모션 선택</code> 그리드의 <strong>포지션 제어</strong> 는 일반 복구가 통하지 않을 때 쓰는 수단입니다. <code>Lock Joints</code> · <code>Position Sit</code> · <code>Position Stand</code> 는 궤적 없이 자세를 강제하므로, <strong>평지에서 로봇이 바닥에 있을 때만</strong> 사용하세요. 관절 단위 수동 복구 패널은 내부용입니다.</p><p>→ <a href="/RBQ/nightly/ko/manual/gui/emergency.html">비상 정지</a></p><h2 id="board-firmware" tabindex="-1">펌웨어 업데이트 — 보드별 상태 <a class="header-anchor" href="#board-firmware" aria-label="Permalink to &quot;펌웨어 업데이트 — 보드별 상태 {#board-firmware}&quot;">​</a></h2><p><strong>정비 › 펌웨어 업데이트</strong> 화면 아래에 <strong>보드별 상태</strong> 표가 더 나옵니다. 표는 여섯 줄(PDU · IF · SIDE_F · SIDE_H · TOP · <code>모터</code>)이고 줄마다 <code>보드</code> · <code>모드</code> · <code>hw</code> · <code>보드 버전</code> · <code>파일 버전</code> · <code>판정</code>을 보여 줍니다. 다리 모터 16개는 모두 같은 펌웨어여야 해서 <code>모터</code> 한 줄로 봅니다.</p><ul><li><code>모드</code>는 앱으로 정상 동작 중이면 <code>앱</code>이라고만 쓰고, 그 밖에는 <code>부트</code> · <code>부트(앱 없음)</code> · <code>대기(STANDBY)</code> 배지로 띄웁니다. 답하지 않는 보드는 <code>없음</code>입니다. 모터 줄은 부트에 남은 모터 수를 씁니다.</li><li><code>판정</code>은 <code>최신</code> · <code>업데이트 가능</code> · <code>다운그레이드</code> · <code>같은 버전</code> · <code>파일 없음</code> · <code>hw 모름</code> · <code>응답 없음</code> · <code>대상 아님</code> · <code>확인 전</code> 가운데 하나입니다. 모터 줄은 다리 전원이 꺼져 모터가 답하지 않으면 <code>다리 꺼짐</code>이고, 모터끼리 펌웨어가 다르면 <code>섞임</code> 배지가 붙습니다. 부트에 남아 <code>hw 모름</code>인 보드는 주황 배지로 띄우고 업데이트할 수 있습니다.</li><li>몸통 보드 줄을 누르면 칸 번호, hw 상태, 펌웨어 대상, 부트 버전, 로봇이 고른 파일 이름, 사유가 펼쳐집니다. 업데이트하면 무엇을 하는지(부트에서 앱으로 보내 확인, 맞는 변형으로 바꿈)도 여기 나옵니다.</li><li><code>모터</code> 줄을 누르면 모터 16개가 관절 이름 · 모드 · 앱 버전 · 판정으로 펼쳐집니다. 어느 모터가 다른지 보는 용도이고, 여기서 모터 하나만 올릴 수는 없습니다.</li><li><code>업데이트 가능</code> · <code>다운그레이드</code> 줄과 부트에 남은 보드에는 <code>업데이트</code> 버튼이 있어 그 보드만 올립니다. <code>모터</code> 줄의 <code>업데이트</code>는 모터 묶음을 올립니다. 위 <code>전체 업데이트</code>와 조건(로봇이 앉아 있거나 제어가 꺼져 있고, 다른 기기가 조종권을 쥐고 있지 않음)과 확인 창이 같습니다. 다른 보드가 <code>확인 필요</code>여도 막히지 않습니다.</li><li>보드 하나를 올릴 때 전원: PDU는 다리·팔 전원을 끄고 올립니다. 모터 묶음은 다리 전원을 켰다가 끝나면 끕니다. 제어가 들어가 있지 않으면 IF · SIDE_F · SIDE_H · TOP은 다리·팔 전원을 건드리지 않습니다. 확인 창에 그 경우의 문장이 나옵니다.</li></ul><p>→ <a href="/RBQ/nightly/ko/manual/gui/maintenance.html#board-firmware">정비</a></p><h2 id="ptz-check" tabindex="-1">PTZ 점검 — 전체 검사 <a class="header-anchor" href="#ptz-check" aria-label="Permalink to &quot;PTZ 점검 — 전체 검사 {#ptz-check}&quot;">​</a></h2><p><strong>정비 › PTZ 점검</strong>의 <code>검사 시작</code> 옆에 <code>기본 검사 시작</code> · <code>에이징 검사 시작</code>이 더해집니다. 둘 다 1~18단계를 돌립니다. 6단계는 전류 영점을 다시 재서 저장하고, 프리셋 단계(11 · 18)는 시작 확인창에서 동의할 때만 돕니다. 에이징 검사는 이어서 축을 공회전시키고(<code>30분</code> · <code>2시간</code> · <code>12시간</code>) 재검사(20) 뒤 최종 보고서를 냅니다.</p><p>→ <a href="/RBQ/nightly/ko/manual/gui/maintenance.html#ptz-check">정비</a></p><h2 id="maintenance" tabindex="-1">정비 — 개발자 섹션 <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;정비 — 개발자 섹션 {#maintenance}&quot;">​</a></h2><p><strong>정비</strong> 화면의 <code>비전</code>, <code>설정 파일</code>, <code>팔</code>은 개발자 모드에서만 보입니다. <code>전원 / 시스템</code>, <code>캘리브레이션</code>, <code>로봇 점검</code>(맨 아래에 원격 점검), <code>펌웨어 업데이트</code>, <code>소프트웨어 업데이트</code>는 모든 사용자에게 열려 있습니다.</p><p>개발자 섹션의 조작은 <strong>연결을 끊거나, 로봇을 주저앉히거나, 데몬 기동 방식을 바꿉니다.</strong> 누르기 전에 각 경고를 읽으세요.</p><p>→ <a href="/RBQ/nightly/ko/manual/gui/maintenance.html">정비</a></p>',58)])])}const u=t(s,[["render",c]]);export{m as __pageData,u as default};
